from torch.distributions import Normal

class AffineCoupling(nn.Module):
    def __init__(self, dim, parity):
        super(AffineCoupling, self).__init__()
        mask = (torch.arange(dim) % 2 == parity).float()
        self.register_buffer('mask', mask)
        self.scale_net = nn.Sequential(
            nn.Linear(dim, dim * 2),
            nn.LeakyReLU(),
            nn.Linear(dim * 2, dim),
            nn.Tanh(),
        )
        self.shift_net = nn.Sequential(
            nn.Linear(dim, dim * 2),
            nn.LeakyReLU(),
            nn.Linear(dim * 2, dim),
        )

    def forward(self, x, logpx=None):
        fixed = x * self.mask
        log_scale = 0.5 * self.scale_net(fixed) * (1 - self.mask)
        shift = self.shift_net(fixed) * (1 - self.mask)
        y = fixed + (1 - self.mask) * (x * torch.exp(log_scale) + shift)
        if logpx is None:
            return y
        return y, logpx + log_scale.sum(dim=-1)

    def inverse(self, y, logpy=None):
        fixed = y * self.mask
        log_scale = 0.5 * self.scale_net(fixed) * (1 - self.mask)
        shift = self.shift_net(fixed) * (1 - self.mask)
        x = fixed + (1 - self.mask) * ((y - shift) * torch.exp(-log_scale))
        if logpy is None:
            return x
        return x, logpy - log_scale.sum(dim=-1)

