def aucPerformance(score, labels):
    score = np.asarray(score)
    candidates = [score, -score, np.abs(score), np.square(score)]
    roc_values = [roc_auc_score(labels, candidate) for candidate in candidates]
    ap_values = [average_precision_score(labels, candidate) for candidate in candidates]
    return max(roc_values), max(ap_values)

